        out["compiles_before"]=json!(count(&stats.compiles));out["lookups_before"]=json!(count(&stats.lookups));out["streams_before"]=json!(count(&stats.streams));
        for _ in 0..j["polls"].as_u64().unwrap(){match stream.as_mut().poll_next(&mut Context::from_waker(Waker::noop())){Poll::Pending=>polls.push(json!({"pending":true})),Poll::Ready(None)=>{polls.push(json!({"end":true}));break},Poll::Ready(Some(Err(e)))=>polls.push(json!({"error":e.to_string()})),Poll::Ready(Some(Ok(c)))=>polls.push(json!({"count":c.rows.len(),"index":c.chunk_index,"last":c.is_last,"rows":c.rows.iter().map(|row|row.iter().map(|(k,v)|(k.clone(),v.to_json_value())).collect::<serde_json::Map<_,_>>()).collect::<Vec<_>>()}))}}
